   136    bool subset (hb_subset_context_t *c, unsigned int available_len) const
   137    {
   138      TRACE_SUBSET (this);
   139      unsigned int num_output_glyphs = c->plan->num_output_glyphs ();
   140
   141      auto* out = c->serializer->start_embed<SBIXStrike> ();
   142      if (unlikely (!out)) return_trace (false);
   143      auto snap = c->serializer->snapshot ();
   144      if (unlikely (!c->serializer->extend (*out, num_output_glyphs + 1))) return_trace (false);
   145      out->ppem = ppem;
   146      out->resolution = resolution;
   147      HBUINT32 head;
   148      head = get_size(num_output_glyphs + 1);
   149
   150      bool has_glyphs = false;
   151      for (unsigned new_gid = 0; new_gid < num_output_glyphs; new_gid++)
   152      {
   153        hb_codepoint_t old_gid;
   154        if (!c->plan->old_gid_for_new_gid (new_gid, &old_gid) ||
   155            unlikely (imageOffsetsZ[old_gid + 1] <= imageOffsetsZ[old_gid] ||
   156                      imageOffsetsZ[old_gid + 1] - imageOffsetsZ[old_gid] <= SBIXGlyph::min_size) ||
   157                      (unsigned int) imageOffsetsZ[old_gid + 1] > available_len)
   158        {
   159          out->imageOffsetsZ[new_gid] = head;
   160          continue;
   161        }
   162        has_glyphs = true;
   163        unsigned int delta = imageOffsetsZ[old_gid + 1] - imageOffsetsZ[old_gid];
   164        unsigned int glyph_data_length = delta - SBIXGlyph::min_size;
   165        if (!(this + imageOffsetsZ[old_gid]).copy (c->serializer, glyph_data_length))
   166          return_trace (false);
   167        out->imageOffsetsZ[new_gid] = head;
   168        head += delta;
   169      }
   170      if (has_glyphs)
   171        out->imageOffsetsZ[num_output_glyphs] = head;
   172      else
   173        c->serializer->revert (snap);
   174      return_trace (has_glyphs);
   175    }
   176
   177    public:
   178    HBUINT16      ppem;           /* The PPEM size for which this strike was designed. */
   179    HBUINT16      resolution;     /* The device pixel density (in PPI) for which this
   180                                   * strike was designed. (E.g., 96 PPI, 192 PPI.) */
   181    protected:
   182    UnsizedArrayOf<LOffsetTo<SBIXGlyph>>
   183                  imageOffsetsZ;  /* Offset from the beginning of the strike data header
   184                                   * to bitmap data for an individual glyph ID. */
   185    public:
   186    DEFINE_SIZE_ARRAY (4, imageOffsetsZ);
   187  };
